const crypto = require('crypto');
const item = $input.item;
const headers = item.json.headers || {};
const timestamp = String(headers['x-istpetdev-timestamp'] || headers['X-IstpetDev-Timestamp'] || '');
const signature = String(headers['x-istpetdev-signature'] || headers['X-IstpetDev-Signature'] || '');
const raw = item.binary && item.binary.data && item.binary.data.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : '';
const payload = item.json.body || {};
const secret = String(item.json.hmacKey || '');
let valid = false;
if (/^\d+$/.test(timestamp) && /^sha256=[a-f0-9]{64}$/.test(signature) && secret && raw) {
  const age = Math.abs(Date.now() / 1000 - Number(timestamp));
  if (age <= 60) {
    const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest();
    const actual = Buffer.from(signature.slice(7), 'hex');
    valid = actual.length === expected.length && crypto.timingSafeEqual(actual, expected);
  }
}
return { json: { valid, payload } };

const fail = (reason) => ({ json: {
  decisions: [], summary: null, model: 'deepseek-chat', promptVersion: 'v2',
  n8nExecutionId: String($execution.id), agentError: String(reason).slice(0, 500)
} });
try {
  if ($json.error) return fail('json.error present: ' + JSON.stringify($json.error));
  let raw = typeof $json.output === 'string' ? $json.output.trim() : $json.output;
  if (typeof raw === 'string' && raw.startsWith('```')) {
    raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  }
  const value = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!value || !Array.isArray(value.decisions) || value.decisions.length === 0 || typeof value.summary !== 'string') return fail('invalid value structure: ' + JSON.stringify(value));
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const decisions = value.decisions.map(decision => ({
    agentDecisionId: String(decision.agentDecisionId || ''),
    explanation: String(decision.explanation || ''),
    driverMessage: String(decision.driverMessage || '')
  }));
  if (decisions.some(d => !uuid.test(d.agentDecisionId) || !d.explanation)) return fail('decisions validation failed: ' + JSON.stringify(decisions));
  return { json: {
    decisions, summary: value.summary, model: 'deepseek-chat', promptVersion: 'v2',
    n8nExecutionId: String($execution.id), agentError: null
  } };
} catch (err) {
  return fail('catch error: ' + err.message);
}
